campaignTrail_temp.questions_json = [
    {
        "model": "campaign_trail.question",
        "pk": 422,
        "fields": {
            "priority": 0,
            "description": "Well, Stevenson, it seems the numerous endorsements and the party seemingly rallying around you have finally clicked in Carter's head, as he has dropped out of the race. Although you weren't anybody's first pick, you probably weren't their last, and you're the nominee now - inspire them like their first choice would.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 415,
        "fields": {
            "priority": 1,
            "description": "Oh, now you’ve done it. You really got strong-armed by the southern delegates and allowed Sparkman to be your running mate? I get that even with Robert Morgan being thrown around as a potential pick, some southerners were still discussing a walkout; this was the best way to keep them in line, but is this really worth the trade-off? The convention floor is in chaos as you present him to the crowd. You clearly aren’t too happy yourself, but the deed is done; there’s no going back now. The southern delegates ooze with delight while everyone else is either stun locked or leaving. Get on stage and salvage what you can from this before it’s too late.\n",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 416,
        "fields": {
            "priority": 2,
            "description": "The punches just swing themselves, don’t they? Ford, nor his surrogates, even have to say anything. A Stevenson/Sparkman ticket, in 1976? Has the Democratic Party gone mad!? The only ones happily marching to the tune of this ticket are exactly the opposite types of voters you wish to attract. We’re bleeding like we’ve been shot by a 50-cal. Gauze up the wound fast, or we’ll be dead by morning.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 430,
        "fields": {
            "priority": 3,
            "description": "Normally, third parties are irrelevant, but this election is all but normal. Eugene McCarthy has somehow not died yet, politically, and is running to the left of us. Before announcing Sparkman as your running mate, McCarthy was polling at not even two percent; now he’s sort of almost leading in multiple states. This can NOT happen if we plan on winning. Sap the soul out of him and crush his bid for President quickly.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 431,
        "fields": {
            "priority": 3,
            "description": "When it rains, it pours, Jimmy Carter, after his close loss in the primary, has yet to endorse us, and it’s not only him who hasn’t felt the urge to support our campaign. We’re losing so much support from so many wings of the party, it’s almost comical. Many high ranking democrats like Humphrey and Muskie have been silent since the convention. Progressives have long gone, traditional democrats are extremely wary of us, and even some southerners are displeased that you're at the top of the ticket and not Sparkman. Which faction do we attempt to reel back in, and how? ",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 444,
        "fields": {
            "priority": 3,
            "description": "We need to stop patching holes in our sinking ship and start getting our message out there. It’s time to start a swing of the battleground states and start changing the minds of voters before they refuse to give our campaign a second look. Hurry and pick a series of states to visit.\n",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 433,
        "fields": {
            "priority": 3,
            "description": "Sparkman this, Sparkman that, I’m over talking about him. We’ve sent him down to stump through Texas, which gives us some time to address the actual issue we would normally be focusing on: foreign policy to start. You've consistently been on the dovish end of the spectrum. But a dove's viewpoint has not always been popular. Will you soften your views at all?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 429,
        "fields": {
            "priority": 3,
            "description": "The signs of economic recovery are there, but some don’t think it’s happening fast enough. There’s been a new bill introduced in the Senate called the Humphrey-Hawkins Full Employment Act. The main goal of this act is to curb unemployment with a steady stream of public jobs for everyone 16 and older. Democrats love it, conservatives don't, and moderates are on the fence. Should we attempt to sway their minds into supporting the bill, or do we moderate a bit?\n",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 445,
        "fields": {
            "priority": 3,
            "description": "Long gone are the days of labeling democrats as the candidates of amnesty, acid, and abortion, as they did with McGovern. Ever since Roe v. Wade, abortion has been a hot-button issue. Women across America, sickened by your running mate, anxiously await your opinion.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 432,
        "fields": {
            "priority": 3,
            "description": "Speaking of social issues that nearly tear families apart - busing. I think we all know where <b>he</b> stands, but what about you? Think wisely, Adlai; your whole coalition could fall apart with your answer here.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 434,
        "fields": {
            "priority": 3,
            "description": "\nSparkman, for all his faults, has given us the gift of bringing the entire southern region under our belt, but he wants to do more. He, somehow, thinks he can be of some use outside of Dixie. I’m telling you, Adlai, he’s only going to hurt where it matters most; we need to keep him chained to the South only, but you get the final word.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 419,
        "fields": {
            "priority": 4,
            "description": "Let’s talk about some down-ballot races really quick. Most democrats facing tough election or re-election bids do not want us to rally with them. There is one exception, however. Howard Metzenbaum is in a tough bid for the Senate against Robert Taft Jr., and has cautiously asked for some assistance, believing your heavy ties to labor can swing the election his way. Some of our campaign staff, however, would rather you visit Pat Moynihan of New York, after he hinted at being open to rallying with you, and bolster your standing in the Northeast. I know you’d rather we do both, but we need to start prepping for the upcoming debate, so choose wisely.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 420,
        "fields": {
            "priority": 5,
            "description": "Speaking of down-ballot races, a few governors' races are expected to be decided by thin margins. The closest race, Missouri, might require your attention. Others have been looking at North Dakota as a possible loss. Unfortunately, we really need to start the debate prep, so we can only visit one state. Where should we head to, Adlai?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 417,
        "fields": {
            "priority": 6,
            "description": "God dammit, I just got confirmation that McCarthy will be debating alongside you and Ford. Hell, even MacBride almost snuck his way onto the debate stage. I don’t know what garbage he’s planning on spewing up there, but he’ll probably be setting his focus mostly on you. We didn’t train much for this scenario, so you need to think up a strategy on the fly and quickly; we're on in an hour.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 418,
        "fields": {
            "priority": 8,
            "description": "They're turning up the heat now. Following the debate, pundits have dug up your ties to the unpopular and corrupt mayor of Chicago, Richard Daley, and your family's long political history. This probably would have been focused on earlier had the whole fiasco with Sparkman not happened. The nation is in dire need of reform; how could you possibly be the one to bring it? If you want any chance, you need to shut down these accusations fast.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 442,
        "fields": {
            "priority": 8,
            "description": "...Speaking of Ford, his strategy so far has been quite smart. He may not be doing many rallies, but he has been filming ads of roaming the white house, shaking hands with voters, and overall being approachable and human. It's helping voters view him as more than just another cog in the machine, but as a respectable, humble, and stand-up guy. We'll need to blunt his personal appeal, but how?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 441,
        "fields": {
            "priority": 8,
            "description": "We need to take action to counter Ford's gains. Let’s try setting our sights on Ford’s running mate. Originally, Bob Dole was practically guaranteed to share the ticket with Ford, but after Sparkman slinked his way onto ours, Ford hasn't been feeling the heat from his right flank as much. The Great Conciliator, Howard Baker of Tennessee, has joined Ford in his quest to secure the White House. How do we even attack one of the most popular politicians of today?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 439,
        "fields": {
            "priority": 3,
            "description": "It's a smaller issue, sure, but being from the Midwest meant you were always at some point going to be asked about tariffs. So, give them a short answer and let's move on to bigger things.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 446,
        "fields": {
            "priority": 3,
            "description": "Capital punishment has started to become a more mainstream issue as of late. Activists and liberals oppose the practice both from a moralistic standpoint and a statistical standpoint, arguing it does not deter people from committing crimes at all. How do you stand on this issue?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 436,
        "fields": {
            "priority": 8,
            "description": "Ford has finally ascended from his lair. He is finally making rounds in the swing states after being couped up in the White House for so long. He’s going on talk shows with some random baseball player from the Cardinals, which seems to be working. This election’s slipping from our hands fast, and we can’t let Ford run up his numbers uninterrupted.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 443,
        "fields": {
            "priority": 8,
            "description": "Just like every election, taxes are up for debate. In March of 1975, President Ford signed the Tax Reduction Act, reducing the tax rates for lower-income families. It also gave lower-income families a tax credit of 400 dollars, provided they had a yearly income of less than four thousand dollars. This act was popular, but with the economic uncertainty still lingering, many wish to know your tax policy. Would you raise, lower, or keep taxes the same?",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 435,
        "fields": {
            "priority": 8,
            "description": "During an interview on NBC, the interviewer asks for your opinion on the recent bailout of New York City. Ford initially refused to help the city at all, but public pressure pushed him to sign the New York City Seasonal Financing Act. You only have a few seconds to think up an answer; make it count.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 437,
        "fields": {
            "priority": 8,
            "description": "Back in 1973, we had an oil shock which caused oil prices to jump by roughly forty percent. This happened from an oil embargo set by the countries of OPEC due to our support of Israel during the Yom Kippur War. Gas prices are still high, and people want to know your solution to this ordeal.\n",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 421,
        "fields": {
            "priority": -2,
            "description": "Tonight's the second and last debate for this election cycle, which, thank God, McCarthy was disqualified from. We argued for three debates, but no dice from Ford’s campaign staff. It’s almost election day, and you need to deliver the final blow to finally bring our momentum back up. Ford has definitely shown himself to be quite strong on the debate stage, so it might be tough to win, but I believe in you, Adlai.",
            "likelihood": 1
        }
    },
    {
        "model": "campaign_trail.question",
        "pk": 447,
        "fields": {
            "priority": -1,
            "description": "This is it, Adlai. Everything rests in the hands of the public now. We need one last push to get these states over the line, but where should we head? And lighten up, will ya? You're as stiff as a brick; voters need to see you at your best.",
            "likelihood": 1
        }
    }
]

campaignTrail_temp.answers_json = [
    {
        "model": "campaign_trail.answer",
        "pk": 3509,
        "fields": {
            "question": 415,
            "description": "We all need to take a minute to look back in time. In 68, Wallace showed us the electoral strength of the South when they're fired up, and we can’t ignore them anymore. For all the southern democrats who have felt like outcasts in this party as of recent, I hear you. I will fight for you; I will fight for those who left, and every single American till my last breath. You have my word."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3513,
        "fields": {
            "question": 416,
            "description": "This all stems from Sparkman's social views, right? Get him out there now and force him to support busing. Very few people like the practice, but no one will call us racist afterwards.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3514,
        "fields": {
            "question": 416,
            "description": "I’m still the same person now as I was before. The progressives have always been supportive of my time in the Senate, minus a vote or two. I’ll act as the five-hundred-dollar wine that makes the two-dollar steak look palatable."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3515,
        "fields": {
            "question": 416,
            "description": "Maybe we could attempt to light his image a little by focusing on his economic views. During his time in the Senate, he pushed two major housing bills and a major urban transportation bill. His record has some bright spots if you take a second to look at it."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3516,
        "fields": {
            "question": 417,
            "description": "The name of the game is to delegitimize McCarthy. It’s been a known fact since the start of his sad little masquerade that he cannot win."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3517,
        "fields": {
            "question": 417,
            "description": "I know that the most important man tonight isn’t any of us—it’s Sparkman. I don’t want to, but I’ll need to be on defense the whole night, especially when topics like busing and abortion come up."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3518,
        "fields": {
            "question": 417,
            "description": "I don’t care whether that loon is up there or not; Ford is the main target. Ford, so far, has done little to stabilize the economy, and I’m going to make him suffer on stage for it."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3520,
        "fields": {
            "question": 418,
            "description": "There’s no good answer here; just keep pressing the Watergate scandal and Ford's pardon of Nixon. Who can you trust more?"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3521,
        "fields": {
            "question": 418,
            "description": "To attack my family lineage, have they no shame? My father was a respectable man, as was his father and his father’s father. "
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3522,
        "fields": {
            "question": 418,
            "description": "Just look at my record in Illinois; to say I have ties to him is clearly false. Mayor Daley and his forces kept shutting down my previous attempts to run for higher office, and I kept on fighting and calling them out for their misdeeds. I’ve been dealing with corrupt officials in Illinois for as long as I can remember, and I’ve always stood against them."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3523,
        "fields": {
            "question": 419,
            "description": "We need to keep reeling back in the Northeast if we really want any shot at victory. Get me to New York before they start wanting to take a couple shots at me."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3524,
        "fields": {
            "question": 419,
            "description": "I doubt I’d receive a warm welcome from New York at this point. Ohio is much more familiar ground for me, and I’ll have a much larger and better impact there. "
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3526,
        "fields": {
            "question": 420,
            "description": "Missouri is shaping up to be the closest race out of all of them. Get me to St. Louis, and hell, let’s bring out Sparkman to tour the rural parts; maybe he could be useful for once. I could also visit Illinois while I'm there."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3527,
        "fields": {
            "question": 420,
            "description": "North Dakota is worth defending. Might as well get some good press in Montana with Judge while we're nearby."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3528,
        "fields": {
            "question": 421,
            "description": "We can’t afford to make any mistakes this close to the election. I’m going to keep it light on policy and avoid making any gaffes."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3529,
        "fields": {
            "question": 421,
            "description": "Let's see if I can split the GOP apart. Betty Ford has been an active supporter of Roe V. Wade; she's been making speeches praising the Supreme Court's decision, a sentiment I think most republicans do not agree with."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3530,
        "fields": {
            "question": 421,
            "description": "It’s time to win this election right here and now. Despite signs of an economic recovery, gas prices are still sky-high, and I'm going to needle him on it. \n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3531,
        "fields": {
            "question": 422,
            "description": "The union workers—they've been a strong force in this party since I can remember; they're practically why I'm able to be here now. Let's make their hearts pound with excitement. A repeal of Taft-Hartley should do the trick."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3532,
        "fields": {
            "question": 422,
            "description": "We'll need to appease Carter's men; they feel bitter, robbed even. I won't touch Taft-Hartley, and I'll make little mention of social issues; they've been known to be quite touchy towards them.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3588,
        "fields": {
            "question": 429,
            "description": "This bill is exactly what we need right now. Unemployment is always a major problem, one that the Humphrey-Hawkins bill will solve."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3589,
        "fields": {
            "question": 429,
            "description": "​While I support this act, there's no way in hell conservatives, or even some Southern Democrats, will be on board with this. I hate to say it, but giving the private sector more leeway might be the only way this bill passes."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3590,
        "fields": {
            "question": 429,
            "description": "I have immense respect for Senator Humphrey and Representative Hawkins, but this act would just be another costly, ineffective mess."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3592,
        "fields": {
            "question": 430,
            "description": "Old Gene is just that—old. The biggest leftists are usually much younger than him and even me. I’m only forty-five, while Gene’s hit the big six-oh. "
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3593,
        "fields": {
            "question": 430,
            "description": "It’s just a simple fact that he can’t win. I couldn't fathom the idea of wasting your voting power on a hopeless endeavor. Voting for McCarthy is essentially voting for Ford, plain and simple. "
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3594,
        "fields": {
            "question": 430,
            "description": "McCarthy is clearly desperate at this point. He tried to run for the nomination in 72’ and it was a complete disaster; this is just his next long shot at staying politically relevant. I doubt we have to worry about his temper tantrum."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3595,
        "fields": {
            "question": 430,
            "description": "It seems Gene is having quite a tough time getting on the ballots in many states. Let's see if we can shove him off some battleground states before he claws his way into them."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3596,
        "fields": {
            "question": 431,
            "description": "We need the South; it’s the only region we’re strong in anymore. We need Jimmy to support us, and who better to convince him than another southerner? This is Sparkman's time to shine."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3597,
        "fields": {
            "question": 431,
            "description": "If we want any chance, we’ll need the progressives. Get Humphrey and Muskie on the line; they know the horrors of the Southern machine and its influence on the party. I would never have chosen Sparkman if I had been given the choice."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3598,
        "fields": {
            "question": 431,
            "description": "States like Indiana, Illinois, and Ohio will be the deciding states in this election, states with heavy labor influence. We must acquire the backing of labor leaders like Leonard Woodcock and George Meany if we want to remain competitive in the Midwest."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3600,
        "fields": {
            "question": 432,
            "description": "I’ve seen how disruptive busing has become over the years. While I will never regurgitate any rhetoric my running mate might spew, I do believe some moderation is needed. I argue for redrawing school district lines."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3601,
        "fields": {
            "question": 432,
            "description": "I can't flip on busing. It'll hurt, but we've been fighting for integration for so long; we won't stop now just because the backlash is getting louder."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3604,
        "fields": {
            "question": 433,
            "description": "Anyone can see where I've stood on foreign policy. I opposed the Vietnam War from the start; I supported ending all aid to South Vietnam. I won't be budging on this issue."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3605,
        "fields": {
            "question": 433,
            "description": "I see which way the wind is starting to blow. The public, sooner or later, will want some defense increases, so let's get ahead of this now and promise some increases."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3606,
        "fields": {
            "question": 433,
            "description": "Wanting and needing are polar opposites. I wish I didn't have to, but I must. I won't touch our defense spending at all, period."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3607,
        "fields": {
            "question": 434,
            "description": "What choice do we really have? We’re going to lose if we don’t go into high gear. Send him through the North and see if he can be the one to change their minds."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3609,
        "fields": {
            "question": 434,
            "description": "Where the hell could he even go? He’d get shot up North, beaten to pulp in the Midwest, and picked up and thrown out of the West Coast. Keep him where he thrives and don't let him take a step near anywhere else."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3610,
        "fields": {
            "question": 434,
            "description": "Compromise is key here. Sparkman's record has been quite pro-farmer, if I do say so myself. Why not have him take a swing through the plains? Sure, we won't win any, but it gets him away from us at least."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3611,
        "fields": {
            "question": 435,
            "description": "“While I did support it, we must review each case carefully and ensure reforms are in place to prevent another episode like this. It cannot become a common occurrence for the federal government to bail out cities and states from their failure to manage their budget.”\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3612,
        "fields": {
            "question": 435,
            "description": "“I, of course, supported the bailout. What I wasn’t too pleased with was Ford's initial hesitancy to provide any semblance of support for the struggling city. “"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3613,
        "fields": {
            "question": 435,
            "description": "“It only makes sense to give extra aid to big cities such as New York. The majority of our population resides in these cities; they need the extra hand to keep things running efficiently.\""
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3614,
        "fields": {
            "question": 435,
            "description": "“Maybe. I would prefer not to speculate on a potential future crisis. We’ll have to see once we get there”"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3615,
        "fields": {
            "question": 436,
            "description": "I’m happy for him. He’s been so cooped up in the White House that he probably hasn’t stepped outside in months. Going that long without any sunlight is very detrimental to one’s health."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3616,
        "fields": {
            "question": 436,
            "description": "After every rally Ford does, we'll hold one at the exact same place. This way we can offset his gains and make a clear contrast between us. I've been rallying in the same places for the last few months now; Jerry only started to do so because it's finally dawning on him that he's about to lose."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3617,
        "fields": {
            "question": 436,
            "description": "Does he really think he can win Michigan? I get it’s his home state, but it won't happen. Ignore these rallies and head to the Northeast. I understand we most likely won’t win Vermont or New Hampshire, but it’s about the message—confidence."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3618,
        "fields": {
            "question": 436,
            "description": "Jerry may not understand that his party has very little positive history with labor. Let’s give them a reminder of the GOP’s numerous attempts to stomp out unions."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3619,
        "fields": {
            "question": 437,
            "description": "The best way to go about this is to start the transition away from oil and coal by investing in solar and wind energy. We, as a country, rely too heavily on oil, and it’s harming our environment."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3620,
        "fields": {
            "question": 437,
            "description": "This whole fiasco was sparked by decades-long tensions between Middle Eastern countries that have been simmering for ages. Creating lasting peace in the Middle East should be our first priority so nothing like this will ever happen again."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3621,
        "fields": {
            "question": 437,
            "description": "Alaska is fertile ground to start increasing our domestic oil production. This event has shown us we cannot rely on the Middle East to keep our best interests at heart."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3622,
        "fields": {
            "question": 437,
            "description": "The main reason for this crisis was our reliance on Saudi Arabia and other Arab countries for our oil. It would be wise to cultivate relations with non-OPEC countries for our oil supply."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3626,
        "fields": {
            "question": 439,
            "description": "I think it comes as no surprise that I'm in favor of higher tariffs. Protecting our workers from foreign competition is paramount in a strong economy."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3627,
        "fields": {
            "question": 439,
            "description": "As you just said, it's a minor issue. Ignore it and focus on other, more pressing issues."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3628,
        "fields": {
            "question": 439,
            "description": "Well, the economy is starting to look up, and that's with a lower tariff rate. The public will probably want a lower tariff rate in the future, and I'll give it to them"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3632,
        "fields": {
            "question": 441,
            "description": "Baker’s record, while impressive, is exactly the way we stunt his appeal. Conservatives have felt completely alienated by Ford's decision. While they definitely won't be voting for us, they very well may stay home instead."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3633,
        "fields": {
            "question": 441,
            "description": "There is a simple answer here—we can’t. I’m not dragging this into the gutter any more than it’s already gone. Attacking the second fiddle usually leads nowhere anyway."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3634,
        "fields": {
            "question": 441,
            "description": "Baker has shaken hands with every senator and president since Johnson. He is just too much of an insider to accurately address the nation's growing concern about whether the government is being truthful with them or not.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3635,
        "fields": {
            "question": 442,
            "description": "Make our own ads. Jerry's not the only one who can film himself being chummy with voters. I'm sure we could visit some factories; shake some hands with the people I know best."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3636,
        "fields": {
            "question": 442,
            "description": "Every time we mention Watergate, we win votes. Ford can't run from his pardoning of Nixon. The stains are still there, a lingering infection; I'm here to scrub the whole White House clean."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3637,
        "fields": {
            "question": 442,
            "description": "If we can't be on personality, we'll beat him on policy. The public's still on our side in terms of how to handle the economy.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3639,
        "fields": {
            "question": 443,
            "description": "Nobody will like it, but we have to raise our taxes, particularly on our most wealthy citizens. I will ensure these tax increases will be implemented fairly and not strangle our most vulnerable citizens."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3640,
        "fields": {
            "question": 443,
            "description": "Now's the time to lock down the conservative democrats for good by promising to cut taxes even more. Lowering taxes is just popular, no matter which way you slice it."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3641,
        "fields": {
            "question": 443,
            "description": "We needed these tax cuts, yes, but I don’t think we should touch the rates any more than we already have."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3643,
        "fields": {
            "question": 444,
            "description": "The Midwest, they can’t abandon me now, not after I’ve stood up for them so many times. Take me from Illinois to Pennsylvania, I’ll reel them back with my record."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3644,
        "fields": {
            "question": 444,
            "description": "If we want any chance in this election, we need to lock down the South for good. Alabama and Mississippi are surely safe, but I’m not so convinced about Virginia or Oklahoma. Let’s take a whistle tour of the border states and some of the southwest while we’re nearby.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3645,
        "fields": {
            "question": 444,
            "description": "God, I cannot believe I will need to campaign in the Northeast. Massachusetts, Rhode Island, Connecticut, and New York all seem to be in desperate need of attention.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3647,
        "fields": {
            "question": 445,
            "description": "I’m sorry to say this, but the Supreme Court may have gone a bit too far in this case. I'm all for women's rights, but I think the states should be handling this."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3650,
        "fields": {
            "question": 445,
            "description": "I'm proud to be pro-choice on the matter. How can we claim to be the greatest nation on earth while denying women the right to decide what's best for their bodies and lives?"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3651,
        "fields": {
            "question": 446,
            "description": "Capital punishment is highly ineffective at curbing crime rates. As president, I will do everything in my power to stop all forms of capital punishment."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3652,
        "fields": {
            "question": 446,
            "description": "I would prefer not to touch this subject much. Most people seem to lean towards letting the states decide, and I'm in agreement, even if I'm personally in disagreement with the practice."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3653,
        "fields": {
            "question": 446,
            "description": "As unfortunate as it is, capital punishment should continue as is. Have you seen some of the things these criminals do? I hate to have to admit it, but the death penalty is needed."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3655,
        "fields": {
            "question": 447,
            "description": "I feel so beat after all this. Take me back to Illinois, and I'll swing through the Midwest one more time."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3656,
        "fields": {
            "question": 447,
            "description": "We’ll make our last push in the Border states. The South is under our spell, but states like Virginia, Kentucky, Missouri, Oklahoma, and New Mexico don't seem fully convinced."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3657,
        "fields": {
            "question": 447,
            "description": "The West is the premier battleground, California to be specific. I’ll be the first Democrat to win it since Johnson. If we get its 45 electoral votes, the election is over."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 3658,
        "fields": {
            "question": 447,
            "description": "I hate how, after all this time, the North is still unconvinced of my candidacy. Get Sparkman to stump in Howard’s stomping grounds while I do one last circuit up there.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 12761,
        "fields": {
            "question": 422,
            "description": "Isn't it obvious? Watergate has to be the biggest scandal America has ever seen, and I'm not letting Ford off the hook. He had the chance to start repairing some trust in Washington; instead, he pardoned Nixon. How could we entrust him with the presidency once more?\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 12923,
        "fields": {
            "question": 432,
            "description": "We need a wide tent if we want to win this election. Say the least offensive thing we can say about busing, then move on to other topics."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 12966,
        "fields": {
            "question": 420,
            "description": "Call me crazy, but I say we head up north to Vermont. This Bernie Sanders fellow is splitting the vote. He may be taking more votes from us, but maybe we could spin it around on Snelling? Spend some time in New Hampshire with Spanos as well."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13044,
        "fields": {
            "question": 441,
            "description": "Call me crazy, but I think we can use this as a way to bring back some progressives. With Howard as Vice President, Ford most definitely would be able to pass most of his agenda- a thought that I doubt many progressives are ecstatic about."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13149,
        "fields": {
            "question": 422,
            "description": "Let's focus on foreign policy. I served in Korea and the Marines. I understand how terrified many were at the thought of fighting in Vietnam; to those who evaded the draft—you will be pardoned.\n"
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13318,
        "fields": {
            "question": 444,
            "description": "California is the name of the game. We won't need any of the Northeast if we win the Golden State itself. We should also swing by Oregon, Washington, and Nevada too while we're around."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13352,
        "fields": {
            "question": 431,
            "description": "We need some really big names to start changing people's minds about our campaign. McGovern made major inroads with Hollywood, and it'd be a waste not to strut some of our newfound star power."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13388,
        "fields": {
            "question": 445,
            "description": "Hedging is our best bet. The majority of voters don't like the sound of banning any and all abortions, but they do agree on banning late-term abortions."
        }
    },
    {
        "model": "campaign_trail.answer",
        "pk": 13466,
        "fields": {
            "question": 417,
            "description": "I don’t care whether that loon is up there or not; Ford is the main target. I’ll need to steer the conversation to more neutral ground. I understand Nixon and Ford's foreign policy is popular, but he won’t expect me to bring it up, and McCarthy’s stance, for certain, is unpopular, allowing me to focus on Ford while he hurts himself."
        }
    }
]

